const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Poyang Lake, Jiangxi Province, China
  const aoi = ee.Geometry.Rectangle([115.78, 28.38, 116.76, 29.80]);
  const date1_start = '2022-07-08';
  const date1_end = '2022-07-12';
  const date2_start = '2022-08-25';
  const date2_end = '2022-08-29';
  const SCALE = 1000; // Use a coarser scale to avoid timeout on large area

  // 2. Data Acquisition & Pre-processing Function
  const maskS2clouds = function(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale optical bands
  };

  const getWaterImage = function(startDate, endDate, geometry) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(geometry)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    // Check if collection is empty
    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
        return null;
    }

    const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
    const maskedImage = maskS2clouds(image);

    // Calculate NDWI = (Green - NIR) / (Green + NIR)
    // Sentinel-2 bands: B3 = Green, B8 = NIR
    const ndwi = maskedImage.normalizedDifference(['B3', 'B8']).rename('ndwi');

    // Threshold to create a water mask. > 0.2 is a common threshold for clear water.
    const water = ndwi.gt(0.2).rename('water');
    return water.selfMask(); // Mask out non-water pixels
  };

  // 3. Image Processing
  const water_img_202207 = getWaterImage(date1_start, date1_end, aoi);
  const water_img_202208 = getWaterImage(date2_start, date2_end, aoi);

  if (!water_img_202207 || !water_img_202208) {
      console.log('No valid, low-cloud images found for one or both date ranges.');
      console.log('Images July 2022:', water_img_202207 ? 'Found' : 'Not Found');
      console.log('Images August 2022:', water_img_202208 ? 'Found' : 'Not Found');
      console.log("C1");
      return;
  }

  // 4. Calculation
  const calculateWaterArea = function(image) {
    const pixelArea = ee.Image.pixelArea(); // Area in square meters
    const waterArea = image.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: SCALE,
        maxPixels: 1e9
    });
    return ee.Number(waterArea.get('water')).divide(1e6); // Convert to square km
  };

  const area_202207_server = calculateWaterArea(water_img_202207);
  const area_202208_server = calculateWaterArea(water_img_202208);

  const area_202207 = area_202207_server.getInfo();
  const area_202208 = area_202208_server.getInfo();

  // 5. Validation & Final Answer
  if (area_202207 === null || area_202208 === null) {
      console.log('Calculation resulted in null. Could be due to no water pixels.');
      console.log(`Area July 2022: ${area_202207}`);
      console.log(`Area August 2022: ${area_202208}`);
      // This is more likely C2 (no valid pixels) if area is null after selfMask
      if (area_202207 === 0 || area_202208 === 0) {
          console.log("C2");
      } else {
          console.log("C3");
      }
      return;
  }

  if (area_202207 === 0 || area_202208 === 0) {
      console.log('No water pixels were found in the area for one of the dates.');
      console.log(`Water Area July 2022 (km^2): ${area_202207.toFixed(2)}`);
      console.log(`Water Area Aug 2022 (km^2): ${area_202208.toFixed(2)}`);
      console.log("C2");
      return;
  }

  const change = area_202208 - area_202207;

  console.log(`Water Area July 2022 (km^2): ${area_202207.toFixed(2)}`);
  console.log(`Water Area Aug 2022 (km^2): ${area_202208.toFixed(2)}`);
  console.log(`Change in Water Area (km^2): ${change.toFixed(2)}`);

  if (area_202208 < area_202207) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
